# Figures de style : exemples et leur nom (distracteurs pris dans les autres figures)
FIG = [("« Cette obscure clarté qui tombe des étoiles » (Corneille)", "oxymore"), ("« Je meurs de soif auprès de la fontaine » (Villon)", "antithèse"),
       ("« Boire un verre »", "métonymie"), ("« Une voile à l'horizon » pour un bateau", "synecdoque"), ("« Ses yeux sont des étoiles »", "métaphore"),
       ("« Il est fort comme un lion »", "comparaison"), ("« Je vous ai dit cent fois de vous taire »", "hyperbole"), ("« Il n'est pas très malin » pour dire qu'il est sot", "litote"),
       ("« Va, je ne te hais point » (Corneille, Le Cid)", "litote"), ("« Pour qui sont ces serpents qui sifflent sur vos têtes ? » (Racine)", "allitération"),
       ("« Les sanglots longs des violons » (Verlaine)", "assonance"), ("« Le soleil se lève, la nature s'éveille, la ville sourit »", "personnification"),
       ("« Il nous a quittés » pour « il est mort »", "euphémisme"), ("« Rome, l'unique objet de mon ressentiment ! Rome… » (Corneille)", "anaphore"),
       ("« Femme nue, femme noire… Femme nue, femme obscure » (Senghor)", "anaphore"), ("« Je suis venu, j'ai vu, j'ai vaincu »", "gradation"),
       ("« Va, cours, vole, et nous venge » (Corneille)", "gradation"), ("« Ô temps, suspends ton vol ! » (Lamartine)", "apostrophe"),
       ("« Quel beau temps ! » dit sous une pluie battante", "antiphrase"), ("« La Fontaine » pour désigner ses fables", "métonymie"),
       ("« Le Roi-Soleil » pour Louis XIV", "périphrase"), ("« L'astre du jour » pour le soleil", "périphrase"), ("« Un silence assourdissant »", "oxymore"),
       ("« Paris a voté » pour les Parisiens", "métonymie"), ("« Ce toit tranquille, où marchent des colombes » (Valéry) pour la mer", "métaphore"),
       ("« Partir, c'est mourir un peu »", "aphorisme"), ("« Heureux qui, comme Ulysse, a fait un beau voyage » (Du Bellay)", "comparaison"),
       ("« Le vent hurle dans la nuit »", "personnification"), ("« Un océan de larmes »", "hyperbole"), ("« Il fait nuit en plein jour »", "paradoxe")]
NOMS = sorted({f for _, f in FIG})
FQ = []
for i, (ex, f) in enumerate(FIG):
    o = [x for x in NOMS if x != f]
    FQ.append((f"Quelle figure de style dans : {ex} ?", f, o[i % len(o)], o[(i + 4) % len(o)], o[(i + 9) % len(o)], "Identifier la figure, puis interpréter son effet dans le texte."))

